"""The dnsmasq configuration Netwatch installs (/etc/dnsmasq.d/netwatch.conf)."""

from __future__ import annotations

from netwatch.config import Settings
from netwatch.errors import ConfigError

CONFIG_PATH = "/etc/dnsmasq.d/netwatch.conf"


def render_config(settings: Settings) -> str:
    if not settings.dns_listen:
        raise ConfigError(
            "NETWATCH_DNS_LISTEN is not set: put the LAN address dnsmasq should answer on in"
            " /etc/netwatch/netwatch.env"
        )
    lines = [
        "# Generated by `netwatch dns config` from /etc/netwatch/netwatch.env.",
        "# deploy/install.sh rewrites this file: change the settings there instead.",
        "",
        "# Answer only on the LAN address, not on every interface. The host's other addresses",
        "# (loopback, a global IPv6 address) stay closed, and systemd-resolved's stub listener",
        "# on 127.0.0.53 keeps working. bind-dynamic also copes with an address that DHCP",
        "# assigns after dnsmasq has started.",
        *(f"listen-address={address}" for address in settings.dns_listen),
        "bind-dynamic",
        "",
        "# Forward to these servers only, not to whatever /etc/resolv.conf lists.",
        "no-resolv",
        *(f"server={server}" for server in settings.dns_upstreams),
        "# Never forward single-label names or reverse lookups for private addresses.",
        "domain-needed",
        "bogus-priv",
        "cache-size=10000",
        "",
        "# Log every step of every query, tagged with a serial number (read by netwatch-dns).",
        "log-queries=extra",
        "log-async=25",
        "",
        "# Netwatch's blocklist. dnsmasq re-reads changed files in this directory itself.",
        # as_posix(): the file is for Linux even when rendered on Windows during development.
        f"hostsdir={settings.blocklist_dir.as_posix()}",
    ]
    return "\n".join(lines) + "\n"
